/// Requires `Default + Children`.
macro_rules! children_static {
    ($t:ty) => {
        impl $t {
            /// Create a default view, then supply its children.
            pub fn children(children: Vec<Box<dyn View>>) -> Self {
                let mut view = <$t>::default();
                view.set_children(children);
                view
            }
        }
    };
}

